pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    if post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64; // Reward better fits
    } else {
        score += (next_item_size - post_residual) as f64; // Penalize poor fits
    }

    if post_residual < mean_residual {
        score -= (mean_residual - post_residual) as f64; // Reward closer to average residual
    } else {
        score += (post_residual - mean_residual) as f64; // Penalize further from average residual
    }

    if fitting_bins_count == 0 {
        score += bin_capacity as f64; // Penalize when no other bins can fit item
    }

    score
}
